import mteb
import json

# Get Scandinavian benchmark
bench = mteb.get_benchmark('MTEB(Scandinavian, v1)')

# Try to load cached results
try:
    results_cache = mteb.load_results(only_main_score=True, require_model_meta=False)
    print(f"Loaded results from cache")
    print(f"Total models in results: {len(results_cache.results)}")

    # Get model names and their scores for Scandinavian tasks
    task_names = [task.metadata.name for task in bench.tasks]
    print(f"Scandinavian tasks: {len(task_names)}")

    # Collect scores by model
    model_scores = {}
    for model_name, model_results in results_cache.results.items():
        if model_results:
            task_scores = []
            for task_result in model_results:
                # Get task name
                task_name = None
                if hasattr(task_result, 'task_name'):
                    task_name = task_result.task_name
                elif isinstance(task_result, dict) and 'task_name' in task_result:
                    task_name = task_result['task_name']

                # Check if task is in Scandinavian benchmark
                if task_name in task_names:
                    # Get the score
                    if hasattr(task_result, 'get_score'):
                        score = task_result.get_score()
                    elif isinstance(task_result, dict) and 'score' in task_result:
                        score = task_result['score']
                    else:
                        score = None

                    if score is not None:
                        task_scores.append(score)

            if task_scores:
                mean_score = sum(task_scores) / len(task_scores)
                model_scores[model_name] = {'mean': mean_score, 'count': len(task_scores)}

    # Sort by mean score
    sorted_models = sorted(model_scores.items(), key=lambda x: x[1]['mean'], reverse=True)
    print(f"\nTop 15 models by mean Scandinavian score:")
    for i, (model_name, scores) in enumerate(sorted_models[:15], 1):
        print(f"{i}. {model_name}: {scores['mean']:.4f} (tasks: {scores['count']})")

    if sorted_models:
        best_model = sorted_models[0][0]
        print(f"\n✓ Best model: {best_model}")
except Exception as e:
    print(f"Error: {e}")
    import traceback
    traceback.print_exc()
